var l={exterior:"Body",interior:"Interior"},i=[{slug:"complex-wash",group:"exterior",name:"Full wash",summary:"A two-phase hand wash with no brushes or abrasives.",description:["We start with a touchless pH-neutral snow foam: it softens road film and lifts grit before a wash mitt ever touches the paint.","The main stage uses the two-bucket method with grit guards; drying is done with filtered warm air and 1200 g/m² microfibre."],includes:["Pre-wash foam and rinse","Hand wash with the two-bucket method","Cleaning wheels and arches","Drying with air and microfibre","Tyre dressing"],duration:"2–3 hours",hours:2.5,priceFrom:90,photo:"det-foam",popular:!0,result:"A clean body with no new micro-scratches."},{slug:"deep-decontamination",group:"exterior",name:"Deep body cleaning",summary:"We remove iron fallout, tree sap and everything water cannot wash away.",description:["The iron remover changes colour when it reacts with brake-pad particles — showing exactly where the body was most contaminated.","After the chemical stage we clay the paint with a synthetic clay: the surface becomes glass-smooth and ready for polishing or protection."],includes:["Full wash","Iron fallout removal","Claying with a synthetic clay","Degreasing before protection","Inspecting the paint under 6500 K light"],duration:"4 hours",hours:4,priceFrom:180,photo:"det-suds",result:"Smooth paint, ready for polishing or protection."},{slug:"tar-removal",group:"exterior",name:"Tar removal",summary:"We remove tar and road grime from sills and bumpers.",description:["Tar spots appear after every drive on fresh asphalt and slowly bake into the clear coat. We dissolve them with a citrus-based solvent that is safe for film and ceramic coatings.","We work especially carefully on sills, the rear of the arches and the lower edge of the bumper."],includes:["Applying tar remover","Hand cleaning of problem areas","Neutralising and rinsing","Inspection under side light"],duration:"1.5 hours",hours:1.5,priceFrom:70,photo:"det-microfiber-red",result:"Sills and bumpers without black spots."},{slug:"wheel-cleaning",group:"exterior",name:"Wheel cleaning",summary:"We take the wheels off and clean the inside of the rims.",description:["Brake dust bakes onto the wheels with every stop. We take the wheels off to reach the inner barrel, the calipers and the arches.","For forged wheels and carbon-ceramic brakes we use acid-free products and soft goat-hair brushes."],includes:["Removing and refitting wheels","Cleaning inside and out","Cleaning calipers and arches","Ceramic protection for wheels (option)","Tightening with a torque wrench"],duration:"3 hours",hours:3,priceFrom:150,photo:"det-wheel",result:"The wheels look new on both sides."},{slug:"detail-cleaning",group:"exterior",name:"Cleaning hard-to-reach areas",summary:"Grilles, badges, door shuts and the gaps between panels.",description:["Dirt in panel gaps and under badges is seen by anyone who opens a door. We use brushes of different stiffness, steam and compressed air.","We pay special attention to honeycomb grilles, air intakes and drains — supercars have more of them than you think."],includes:["Door, bonnet and boot shuts","Grilles and air intakes","Badges and emblems","Blowing out gaps with compressed air"],duration:"2 hours",hours:2,priceFrom:110,photo:"det-headlight",result:"Clean where an ordinary wash cannot reach."},{slug:"paint-polishing",group:"exterior",name:"Paint polishing",summary:"Multi-stage paint correction with thickness control.",description:["Before polishing we measure the paint thickness on every panel. If there is less than 90 µm of clear coat, we choose a gentle process and tell you honestly which defects will remain.","The cutting stage removes holograms and scratches, the finishing stage brings back depth of colour. Every panel is checked under three kinds of light: diffused, spot and full-spectrum sunlight."],includes:["Paint thickness readings at 40+ points","Two- or three-stage correction","Removing holograms and swirls","Finishing polish to a mirror shine","Before-and-after photo report"],duration:"2–3 days",hours:20,priceFrom:890,variablePrice:!0,photo:"det-polish",popular:!0,result:"Up to 95% of paint defects removed, with the depth of colour of a new car."},{slug:"gloss-restoration",group:"exterior",name:"Gloss restoration",summary:"A one-step polish for cars in good condition.",description:["For cars that are washed regularly but have lost their “wet” gloss. A single stage with an all-in-one compound removes light swirls and refreshes the colour.","The session takes one day and removes a minimum of clear coat — good preparation before a sale or a new season."],includes:["Deep body cleaning","One-step polish","Protective sealant for 3 months"],duration:"1 day",hours:8,priceFrom:420,variablePrice:!0,photo:"det-microfiber",result:"Fresh, rich colour in a single day."},{slug:"ceramic-coating",group:"exterior",name:"Ceramic coating",summary:"A hard, clear layer that lasts up to five years.",description:["A ceramic coating is a layer of silicon dioxide about 1–2 µm thick that bonds chemically with the clear coat. It is harder than factory lacquer, repels water and dirt, and resists car-care chemicals.","We apply the coating in a separate bay with controlled temperature and humidity, then leave the car overnight under infrared lamps to cure."],includes:["Deep cleaning and paint preparation","Degreasing before application","Coating for body, wheels and glass","Overnight curing under infrared lamps","Certificate and scheduled check-up"],duration:"2 days",hours:16,priceFrom:1200,variablePrice:!0,photo:"det-beading",popular:!0,result:"Water beads up and rolls off, and washing takes half the time."},{slug:"ppf",group:"exterior",name:"Paint protection film (PPF)",summary:"Clear polyurethane armour against chips and scratches.",description:["Polyurethane film about 200 µm thick absorbs stone impacts and light scratches. Its top layer heals minor marks when warmed by the sun or warm water.","Templates are cut on a plotter for the exact model, and edges are wrapped inside the panels wherever possible — so the film is invisible even up close."],includes:["Preparing and degreasing the body","Cut on a plotter from the model’s templates","Edges wrapped inside the panels","A check-up warm-up and inspection after 48 hours","Gloss or matte film, your choice"],duration:"3–5 days",hours:36,priceFrom:2400,variablePrice:!0,photo:"det-film-orange",popular:!0,result:"The paint is protected from chips, and the film is invisible even up close."},{slug:"window-tint",group:"exterior",name:"Window tinting",summary:"Ceramic and heat-rejecting films within legal light-transmission limits.",description:["We use ceramic films: they block up to 99% of UV and a large share of infrared without interfering with GPS or keyless systems.","Before fitting we measure the glass’s light transmission and choose the film so the result meets the requirements for front windows."],includes:["Measuring glass light transmission","Plotter cutting","Fitted without removing the seals","Check measurement after fitting"],duration:"1 day",hours:6,priceFrom:380,photo:"urus-black",result:"A cool cabin and leather protected from fading."},{slug:"interior-deep-clean",group:"interior",name:"Deep interior cleaning",summary:"A full interior clean, with seats removed if needed.",description:["We work with steam, an extractor and soft brushes. Every surface gets its own product: leather, Alcantara, carpet and carbon each need a different approach.","After cleaning, the cabin is dried with a dehumidifier so no moisture is left in the seat padding."],includes:["Deep cleaning of seats and carpets","Alcantara cleaning","Steam treatment","Drying with a dehumidifier","Odour neutralisation"],duration:"1 day",hours:8,priceFrom:350,photo:"det-dash-a",popular:!0,result:"A cabin without stains, smells or signs of use."},{slug:"leather-cleaning",group:"interior",name:"Cleaning leather parts",summary:"Gentle leather cleaning that does not dry it out.",description:["Perforated and Nappa leather absorb dirt into the pores. We use pH-neutral foam and horsehair brushes so the protective top coat is not damaged.","Light leather is also cleaned of dye transfer from denim."],includes:["Testing the product on a hidden spot","Foam leather cleaning","Perforation cleaning","Removing dye transfer"],duration:"4 hours",hours:4,priceFrom:190,photo:"int-tan",result:"The leather regains its original colour and matte texture."},{slug:"leather-conditioning",group:"interior",name:"Leather conditioning",summary:"Nourishes the leather and protects it from cracking and fading.",description:["The conditioner restores the leather’s suppleness and adds a protective layer against UV and wear. The leather does not shine or feel slippery.","We recommend it every three to four months, especially for cars that are often parked in the sun."],includes:["Cleaning before application","Applying conditioner","UV protection","Final wipe with microfibre"],duration:"2 hours",hours:2,priceFrom:120,photo:"int-brown",result:"Leather that feels soft, with no glossy shine."},{slug:"headliner-cleaning",group:"interior",name:"Headliner cleaning",summary:"Gentle headliner cleaning that does not make the lining sag.",description:["The headliner is glued to its backing, so it must never be soaked. We work with dry foam and microfibre so the adhesive keeps its grip.","We are especially careful with starlight headliners and Alcantara."],includes:["Dry foam cleaning","Cleaning sun visors and lights","Stain removal","Checking colour evenness"],duration:"3 hours",hours:3,priceFrom:140,photo:"int-white",result:"An even headliner colour without streaks."},{slug:"plastic-care",group:"interior",name:"Plastic care",summary:"Cleaning and matte protection for plastics, carbon and piano black.",description:["Piano-black gloss trim scratches from any cloth. We clean it separately and polish it by hand if needed.","Matte plastics get antistatic protection without a greasy shine."],includes:["Cleaning panels and console","Polishing gloss trim","Antistatic protection","Cleaning screens with a safe product"],duration:"2 hours",hours:2,priceFrom:90,photo:"det-dash-b",result:"The factory texture of the plastic, without glare."},{slug:"vents-cleaning",group:"interior",name:"Cleaning the air vents",summary:"We clean the grilles and ducts and treat the air-conditioning system.",description:["Dust in the vents is blown around the cabin every time the climate control runs. We clean the louvres with brushes and compressed air, then treat the evaporator.","On request we replace the cabin filter with a carbon one."],includes:["Cleaning the vent louvres","Blowing out channels","Antibacterial treatment of the evaporator","Replacing the cabin filter (option)"],duration:"1.5 hours",hours:1.5,priceFrom:80,photo:"int-portofino",result:"Fresh cabin air without the smell of dust."},{slug:"interior-complex",group:"interior",name:"Full interior clean",summary:"Regular interior care between deep cleans.",description:["We vacuum, clean every surface and the inside of the glass. Ideal for keeping the cabin fresh after a deep clean or before an important trip.","Boot carpets and floor mats are cleaned separately."],includes:["Vacuuming the cabin and boot","Cleaning every surface","Glass and mirrors inside","Floor mat cleaning"],duration:"3 hours",hours:3,priceFrom:160,photo:"int-red",result:"A tidy cabin, ready for the road."}];function c(e){return i.find(t=>t.slug===e)}var h={coupe:"Coupé and saloon",suv:"SUV"},n=[{id:"essential",name:"Essential Care",pitch:"Regular care for a car that is driven every day.",price:{coupe:290,suv:350},duration:"1 day",protection:"Sealant for 3 months",extras:["Ozone treatment","Tyre dressing"]},{id:"premium",name:"Premium Care",pitch:"Restored gloss and a ceramic coating for two years.",price:{coupe:1190,suv:1420},duration:"3 days",protection:"Ceramic for 2 years",extras:["Ceramic for wheels","Rain repellent on the windscreen"]},{id:"ultimate",name:"Ultimate Protection",pitch:"Full correction, film on the front and a ceramic coating on top.",price:{coupe:4900,suv:5800},duration:"6 days",protection:"PPF + ceramic for 5 years",extras:["Scheduled check-up after 30 days","Leather and Alcantara protection","Delivery by transporter"]}],d=[{label:"A full wash and wheel cleaning",values:{essential:!0,premium:!0,ultimate:!0}},{label:"Deep body cleaning",values:{essential:"Chemical",premium:"Chemicals + clay",ultimate:"Chemicals + clay"}},{label:"Polishing",values:{essential:!1,premium:"One-step",ultimate:"Multi-stage"}},{label:"Paint protection",values:{essential:"Sealant",premium:"Ceramic",ultimate:"PPF + ceramic"}},{label:"PPF film",values:{essential:!1,premium:!1,ultimate:"Front end"}},{label:"Interior clean",values:{essential:"Full",premium:"Full",ultimate:"Deep cleaning"}},{label:"Leather cleaning and care",values:{essential:!1,premium:!0,ultimate:!0}},{label:"Before-and-after photo report",values:{essential:!1,premium:!0,ultimate:!0}},{label:"Courtesy car",values:{essential:!1,premium:!1,ultimate:!0}}],u=[{id:"ppf",name:"PPF film",thickness:"≈ 200 µm",weight:5,note:"The polyurethane layer takes stone impacts and self-heals light scratches when warmed.",service:"ppf"},{id:"ceramic",name:"Ceramic",thickness:"1–2 µm",weight:.6,note:"A hard, clear film of silicon dioxide. It repels water and makes washing easier.",service:"ceramic-coating"},{id:"clear",name:"Factory clear coat",thickness:"40–60 µm",weight:2.4,note:"This is the layer that gets polished. Each correction removes 2–5 µm — which is why thickness is measured first.",service:"paint-polishing"},{id:"base",name:"Base coat",thickness:"15–25 µm",weight:1.2,note:"The pigment that gives the colour. If a scratch reaches it, a local respray is needed."},{id:"primer",name:"Primer",thickness:"20–30 µm",weight:1.3,note:"Bonds the paint to the metal and levels the surface."},{id:"metal",name:"Metal or carbon",thickness:"0.7–1 mm",weight:2,note:"The base of the body. On supercars some panels are made of carbon fibre."}],r=["complex-wash","deep-decontamination","wheel-cleaning","interior-complex","plastic-care"],a=[...r,"gloss-restoration","ceramic-coating","leather-cleaning","leather-conditioning"],o=[...a,"paint-polishing","ppf","interior-deep-clean","detail-cleaning","tar-removal"],s={essential:r,premium:a,ultimate:o};function p(e){return n.filter(t=>s[t.id].includes(e))}export{l as a,i as b,c,h as d,n as e,d as f,u as g,p as h};
